#[derive(Debug, Clone)]
struct TxIngressAoemOwnershipGatesV1 {
    production_candidate: bool,
    semantic_graph_v3_required: bool,
    shadow: bool,
    compare: bool,
    source: String,
    explicit: bool,
}

fn bool_param_from_object_any_v1(
    obj: &serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<bool> {
    keys.iter()
        .filter_map(|key| obj.get(*key))
        .find_map(|value| match value {
            serde_json::Value::Bool(value) => Some(*value),
            serde_json::Value::Number(number) => number.as_u64().map(|value| value != 0),
            serde_json::Value::String(raw) => parse_bool_token_v1(raw),
            _ => None,
        })
}

fn tx_ingress_aoem_ownership_gates_from_params_v1(
    params: &serde_json::Value,
) -> TxIngressAoemOwnershipGatesV1 {
    if let Some(config) = params
        .get("aoem_owned_gate_config")
        .and_then(|value| value.as_object())
    {
        let source = config
            .get("source")
            .and_then(|value| value.as_str())
            .filter(|value| !value.trim().is_empty())
            .unwrap_or("explicit_params")
            .to_string();
        let mut gates = TxIngressAoemOwnershipGatesV1 {
            production_candidate: bool_param_from_object_any_v1(
                config,
                &["production_candidate", "productionCandidate"],
            )
            .unwrap_or(true),
            semantic_graph_v3_required: bool_param_from_object_any_v1(
                config,
                &[
                    "semantic_graph_v3_required",
                    "semanticGraphV3Required",
                    "full_business_compute_required",
                    "fullBusinessComputeRequired",
                    "generic_native_compute_required",
                ],
            )
            .unwrap_or(false),
            shadow: bool_param_from_object_any_v1(config, &["shadow"]).unwrap_or(false),
            compare: bool_param_from_object_any_v1(config, &["compare"]).unwrap_or(false),
            source,
            explicit: true,
        };
        pin_tx_ingress_aoem_ownership_gates_to_environment_v1(&mut gates);
        return gates;
    }

    let production_candidate = bool_param_any_v1(
        params,
        &[
            "tx_ingress_aoem_gate_config_production_candidate",
            "aoem_gate_production_candidate",
            "aoem_production_candidate",
        ],
    );
    let shadow = bool_param_any_v1(
        params,
        &[
            "tx_ingress_aoem_gate_config_shadow",
            "aoem_gate_shadow",
            "aoem_shadow",
        ],
    );
    let semantic_graph_v3_required = bool_param_any_v1(
        params,
        &[
            "tx_ingress_aoem_gate_config_semantic_graph_v3_required",
            "aoem_semantic_graph_v3_required",
            "tx_ingress_aoem_gate_config_full_business_compute_required",
            "aoem_full_business_compute_required",
            "generic_native_compute_required",
        ],
    );
    let compare = bool_param_any_v1(
        params,
        &[
            "tx_ingress_aoem_gate_config_compare",
            "aoem_gate_compare",
            "aoem_compare",
        ],
    );
    if production_candidate.is_some()
        || semantic_graph_v3_required.is_some()
        || shadow.is_some()
        || compare.is_some()
    {
        let source = params
            .get("tx_ingress_aoem_gate_config_source")
            .or_else(|| params.get("aoem_gate_config_source"))
            .and_then(|value| value.as_str())
            .filter(|value| !value.trim().is_empty())
            .unwrap_or("explicit_params")
            .to_string();
        let mut gates = TxIngressAoemOwnershipGatesV1 {
            production_candidate: production_candidate.unwrap_or(false),
            semantic_graph_v3_required: semantic_graph_v3_required.unwrap_or(false),
            shadow: shadow.unwrap_or(false),
            compare: compare.unwrap_or(false),
            source,
            explicit: true,
        };
        pin_tx_ingress_aoem_ownership_gates_to_environment_v1(&mut gates);
        return gates;
    }

    TxIngressAoemOwnershipGatesV1 {
        production_candidate: native_aoem_native_tx_batch_production_candidate_enabled_v1(),
        semantic_graph_v3_required: false,
        shadow: native_aoem_native_tx_batch_shadow_enabled_v1(),
        compare: native_aoem_native_tx_batch_compare_enabled_v1(),
        source: "env_fallback".to_string(),
        explicit: false,
    }
}

fn pin_tx_ingress_aoem_ownership_gates_to_environment_v1(
    gates: &mut TxIngressAoemOwnershipGatesV1,
) {
    // Request parameters may opt into stricter validation, but they may never
    // turn off an ownership/compare gate pinned by the node operator.
    gates.production_candidate |= native_aoem_native_tx_batch_production_candidate_enabled_v1();
    gates.shadow |= native_aoem_native_tx_batch_shadow_enabled_v1();
    gates.compare |= native_aoem_native_tx_batch_compare_enabled_v1();
}

fn native_aoem_owned_runtime_config_v1() -> Result<AoemRuntimeConfig> {
    // `AoemRuntimeConfig::apply_process_env` publishes the already-open core
    // runtime as `AOEM_FFI_PERSIST_BACKEND=none`. That internal projection must
    // not disable the product's later AOEM-owned state boundary. The NOVOVM
    // variable is the explicit operator override; otherwise FULLMAX core uses
    // its storage-provider RocksDB surface for owned state.
    let persist_backend_explicit = std::env::var("NOVOVM_AOEM_PERSIST_BACKEND").is_ok();
    let mut runtime = AoemRuntimeConfig::from_env()?;
    if !persist_backend_explicit && runtime.persist_backend.trim().eq_ignore_ascii_case("none") {
        runtime.persist_backend = "rocksdb".to_string();
    }
    Ok(runtime)
}

fn tx_ingress_string_param_any_v1(params: &serde_json::Value, keys: &[&str]) -> Option<String> {
    keys.iter()
        .filter_map(|key| params.get(*key))
        .find_map(|value| {
            value
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string)
        })
}

fn native_persistence_selected_by_request_v1(params: &serde_json::Value) -> bool {
    NOV_NATIVE_PERSISTENCE_REQUEST_KEYS_V1
        .iter()
        .any(|key| params.get(*key).is_some())
}

fn tx_ingress_real_callsite_v1(
    params: &serde_json::Value,
    production_candidate_enabled: bool,
    default_callsite: &str,
) -> String {
    if let Some(callsite) = tx_ingress_string_param_any_v1(
        params,
        &[
            "tx_ingress_real_callsite",
            "tx_ingress_callsite",
            "tx_ingress_called_by",
        ],
    ) {
        return callsite;
    }
    if native_aoem_runtime_worker_pipeline_enabled_v1() && production_candidate_enabled {
        return "aoem_runtime_worker".to_string();
    }
    default_callsite.to_string()
}

struct AoemRuntimeWorkerPipelineFieldsInputV1<'a> {
    params: &'a serde_json::Value,
    production_candidate_enabled: bool,
    tx_ingress_real_callsite: &'a str,
    tx_count: u64,
    batch_built: bool,
    result_ready: bool,
    result_verified: bool,
}

fn insert_aoem_runtime_worker_pipeline_fields_v1(
    out: &mut serde_json::Map<String, serde_json::Value>,
    input: AoemRuntimeWorkerPipelineFieldsInputV1<'_>,
) {
    let AoemRuntimeWorkerPipelineFieldsInputV1 {
        params,
        production_candidate_enabled,
        tx_ingress_real_callsite,
        tx_count,
        batch_built,
        result_ready,
        result_verified,
    } = input;
    let pipeline_enabled = native_aoem_runtime_worker_pipeline_enabled_v1();
    let pipeline_mode = if pipeline_enabled {
        "aoem_runtime_worker_pipeline"
    } else {
        "legacy_receiver_tick"
    };
    let called_by_aoem_runtime_worker = tx_ingress_real_callsite == "aoem_runtime_worker";
    let network_receiver_calls_production_tx_ingress =
        production_candidate_enabled && !called_by_aoem_runtime_worker;
    let explicit_object_ready_count = params
        .get("network_receiver_object_ready_count")
        .and_then(|value| value.as_u64());
    let object_ready_count = explicit_object_ready_count.unwrap_or(tx_count);
    let batch_ready_count = u64::from(batch_built && tx_count > 0);
    let commitment_ok_count = u64::from(batch_built && tx_count > 0);
    let worker_batch_received_count = u64::from(pipeline_enabled && batch_built && tx_count > 0);
    let worker_tx_ingress_call_count =
        u64::from(pipeline_enabled && called_by_aoem_runtime_worker && tx_count > 0);
    let worker_result_ready_count = u64::from(pipeline_enabled && result_ready);
    let finality_verified_count = u64::from(pipeline_enabled && result_verified);
    let inflight_enabled = native_aoem_inflight_batch_enabled_v1();
    let inflight_limit = native_aoem_inflight_batch_limit_v1();
    let inflight_batch_size = native_aoem_inflight_batch_size_v1();
    let inflight_result_drain_budget = native_aoem_inflight_result_drain_budget_v1();
    let inflight_submitted_count = u64::from(inflight_enabled && worker_batch_received_count > 0);
    let inflight_completed_count = u64::from(inflight_enabled && worker_result_ready_count > 0);
    let inflight_failed_count =
        u64::from(inflight_enabled && worker_batch_received_count > 0 && !result_ready);
    let inflight_timeout_count = 0u64;
    let inflight_active_count = inflight_submitted_count.saturating_sub(inflight_completed_count);
    let worker_submit_queue_depth = batch_ready_count.saturating_sub(worker_batch_received_count);
    let worker_result_queue_depth =
        worker_result_ready_count.saturating_sub(finality_verified_count);
    let inflight_backpressure_reason = if !inflight_enabled {
        "disabled"
    } else if inflight_active_count >= inflight_limit && worker_submit_queue_depth > 0 {
        "aoem_inflight_backpressure_limit_reached"
    } else if worker_submit_queue_depth > 0
        && inflight_active_count < inflight_limit
        && inflight_submitted_count == 0
    {
        "aoem_inflight_submit_stall"
    } else if worker_result_queue_depth > 0 && finality_verified_count == 0 {
        "aoem_inflight_result_drain_stall"
    } else {
        "none"
    };
    let inflight_oldest_batch_id = if inflight_active_count > 0 {
        params
            .get("aoem_runtime_worker_batch_id")
            .cloned()
            .unwrap_or_else(|| serde_json::json!(0u64))
    } else {
        serde_json::Value::Null
    };
    let inflight_proof_count_finalized = result_verified;
    let inflight_proof_count_sample_source = if inflight_enabled && result_verified {
        "inflight_completed_batch_result"
    } else if inflight_enabled {
        "inflight_batch_pending"
    } else {
        "legacy_pipeline_batch_result"
    };

    out.insert(
        "receiver_pipeline_mode".to_string(),
        serde_json::json!(pipeline_mode),
    );
    out.insert(
        "network_receiver_object_ready_count".to_string(),
        serde_json::json!(object_ready_count),
    );
    out.insert(
        "network_receiver_calls_production_tx_ingress".to_string(),
        serde_json::json!(network_receiver_calls_production_tx_ingress),
    );
    out.insert(
        "object_assembler_batch_ready_count".to_string(),
        serde_json::json!(batch_ready_count),
    );
    out.insert(
        "object_assembler_commitment_ok_count".to_string(),
        serde_json::json!(commitment_ok_count),
    );
    out.insert(
        "aoem_runtime_worker_batch_received_count".to_string(),
        serde_json::json!(worker_batch_received_count),
    );
    out.insert(
        "aoem_runtime_worker_tx_ingress_call_count".to_string(),
        serde_json::json!(worker_tx_ingress_call_count),
    );
    out.insert(
        "aoem_runtime_worker_tx_ingress_callsite".to_string(),
        if called_by_aoem_runtime_worker {
            serde_json::json!(tx_ingress_real_callsite)
        } else {
            serde_json::Value::Null
        },
    );
    out.insert(
        "aoem_runtime_worker_result_ready_count".to_string(),
        serde_json::json!(worker_result_ready_count),
    );
    out.insert(
        "aoem_inflight_batch_enabled".to_string(),
        serde_json::json!(inflight_enabled),
    );
    out.insert(
        "aoem_inflight_batch_limit".to_string(),
        serde_json::json!(inflight_limit),
    );
    out.insert(
        "aoem_inflight_batch_size".to_string(),
        serde_json::json!(inflight_batch_size),
    );
    out.insert(
        "aoem_inflight_result_drain_budget".to_string(),
        serde_json::json!(inflight_result_drain_budget),
    );
    out.insert(
        "aoem_inflight_batch_active_count".to_string(),
        serde_json::json!(inflight_active_count),
    );
    out.insert(
        "aoem_runtime_worker_inflight_batch_count".to_string(),
        serde_json::json!(inflight_active_count),
    );
    out.insert(
        "aoem_runtime_worker_max_inflight_batches".to_string(),
        serde_json::json!(inflight_limit),
    );
    out.insert(
        "aoem_inflight_batch_submitted_count".to_string(),
        serde_json::json!(inflight_submitted_count),
    );
    out.insert(
        "aoem_inflight_batch_completed_count".to_string(),
        serde_json::json!(inflight_completed_count),
    );
    out.insert(
        "aoem_inflight_batch_failed_count".to_string(),
        serde_json::json!(inflight_failed_count),
    );
    out.insert(
        "aoem_inflight_batch_timeout_count".to_string(),
        serde_json::json!(inflight_timeout_count),
    );
    out.insert(
        "aoem_inflight_batch_backpressure_reason".to_string(),
        serde_json::json!(inflight_backpressure_reason),
    );
    out.insert(
        "aoem_runtime_worker_submit_queue_depth".to_string(),
        serde_json::json!(worker_submit_queue_depth),
    );
    out.insert(
        "aoem_runtime_worker_result_queue_depth".to_string(),
        serde_json::json!(worker_result_queue_depth),
    );
    out.insert(
        "aoem_runtime_worker_submit_delta".to_string(),
        serde_json::json!(inflight_submitted_count),
    );
    out.insert(
        "aoem_runtime_worker_result_drain_delta".to_string(),
        serde_json::json!(inflight_completed_count),
    );
    out.insert(
        "aoem_runtime_worker_inflight_oldest_age_ms".to_string(),
        serde_json::json!(0u64),
    );
    out.insert(
        "aoem_runtime_worker_inflight_oldest_batch_id".to_string(),
        inflight_oldest_batch_id,
    );
    out.insert(
        "aoem_runtime_worker_result_reorder_count".to_string(),
        serde_json::json!(0u64),
    );
    out.insert(
        "aoem_runtime_worker_canonical_close_ordered".to_string(),
        serde_json::json!(true),
    );
    out.insert(
        "aoem_runtime_worker_ledger_close_ordered".to_string(),
        serde_json::json!(true),
    );
    out.insert(
        "aoem_runtime_worker_proof_count_finalized".to_string(),
        serde_json::json!(inflight_proof_count_finalized),
    );
    out.insert(
        "aoem_runtime_worker_proof_count_sample_source".to_string(),
        serde_json::json!(inflight_proof_count_sample_source),
    );
    out.insert(
        "finality_report_worker_result_verified_count".to_string(),
        serde_json::json!(finality_verified_count),
    );
    out.insert(
        "finality_report_worker_final_report_written".to_string(),
        serde_json::json!(result_ready),
    );
    out.insert(
        "tx_ingress_real_callsite".to_string(),
        serde_json::json!(tx_ingress_real_callsite),
    );
    out.insert(
        "tx_ingress_called_by_network_receiver".to_string(),
        serde_json::json!(network_receiver_calls_production_tx_ingress),
    );
    out.insert(
        "tx_ingress_called_by_aoem_runtime_worker".to_string(),
        serde_json::json!(called_by_aoem_runtime_worker),
    );
    out.insert(
        "receiver_pipeline_stage_lag".to_string(),
        serde_json::json!({
            "network_to_object": object_ready_count.saturating_sub(tx_count),
            "object_to_aoem_worker": batch_ready_count.saturating_sub(worker_batch_received_count),
            "aoem_worker_to_finality": worker_result_ready_count.saturating_sub(finality_verified_count),
        }),
    );
    out.insert(
        "receiver_pipeline_backpressure_reason".to_string(),
        serde_json::json!("none"),
    );
}

fn parse_bool_token_v1(raw: &str) -> Option<bool> {
    let value = raw.trim();
    if value == "1"
        || value.eq_ignore_ascii_case("true")
        || value.eq_ignore_ascii_case("yes")
        || value.eq_ignore_ascii_case("on")
    {
        return Some(true);
    }
    if value == "0"
        || value.eq_ignore_ascii_case("false")
        || value.eq_ignore_ascii_case("no")
        || value.eq_ignore_ascii_case("off")
    {
        return Some(false);
    }
    None
}

fn bool_param_any_v1(params: &serde_json::Value, keys: &[&str]) -> Option<bool> {
    keys.iter()
        .filter_map(|key| params.get(*key))
        .find_map(|value| match value {
            serde_json::Value::Bool(value) => Some(*value),
            serde_json::Value::Number(number) => number.as_u64().map(|value| value != 0),
            serde_json::Value::String(raw) => parse_bool_token_v1(raw),
            _ => None,
        })
}

fn native_send_raw_transaction_pipeline_only_v1(params: &serde_json::Value) -> bool {
    if bool_env_default_v1(NOV_NATIVE_SEND_RAW_TRANSACTION_PIPELINE_ONLY_ENV, false) {
        return true;
    }
    bool_param_any_v1(
        params,
        &[
            "pipeline_only",
            "pipelineOnly",
            "pending_only",
            "pendingOnly",
        ],
    )
    .unwrap_or(false)
}

fn usize_env_default_v1(name: &str, default: usize) -> usize {
    std::env::var(name)
        .ok()
        .and_then(|raw| raw.trim().parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(default)
}

fn native_aoem_batch_max_size_v1() -> usize {
    usize_env_default_v1(
        NOV_NATIVE_AOEM_BATCH_MAX_SIZE_ENV,
        NOV_NATIVE_AOEM_BATCH_MAX_SIZE_DEFAULT_V1,
    )
}

const fn default_true_v1() -> bool {
    true
}

fn normalize_hex_token_v1(raw: &str) -> Option<String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return None;
    }
    let token = trimmed
        .strip_prefix("0x")
        .or_else(|| trimmed.strip_prefix("0X"))
        .unwrap_or(trimmed)
        .to_ascii_lowercase();
    if token.is_empty() || !token.bytes().all(|b| b.is_ascii_hexdigit()) {
        return None;
    }
    Some(token)
}

fn normalize_eth_address_policy_v1(raw: &str) -> Option<String> {
    let token = normalize_hex_token_v1(raw)?;
    if token.len() == 40 {
        Some(format!("0x{token}"))
    } else {
        None
    }
}

fn to_hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push_str(&format!("{byte:02x}"));
    }
    out
}

fn sha256_bytes_v1(parts: &[&[u8]]) -> [u8; 32] {
    use sha2::{Digest, Sha256};

    let mut hasher = Sha256::new();
    for part in parts {
        hasher.update(part);
    }
    hasher.finalize().into()
}

fn native_aoem_semantic_entry_v1() -> &'static str {
    "aoem.ops_wire_v1.native_asset_semantic_ingress"
}

fn native_aoem_raw_tx_batch_precommit_entry_v1() -> &'static str {
    "aoem.ops_wire_v1.native_raw_tx_batch_precommit"
}

fn native_execution_request_plan_id_v1(
    request: &NovExecutionRequestV1,
    subject_meta: &NovExecutionSubjectMetaV1,
) -> u64 {
    let target = execution_target_label_v1(&request.target);
    let digest = sha256_bytes_v1(&[
        b"novovm-native-aoem-semantic-plan-id-v1",
        request.tx_hash.as_slice(),
        target.as_bytes(),
        request.method.as_bytes(),
        subject_meta.account_id.as_bytes(),
        &request.nonce.to_le_bytes(),
    ]);
    let mut out = [0u8; 8];
    out.copy_from_slice(&digest[..8]);
    u64::from_le_bytes(out)
}

fn build_native_execution_aoem_ops_wire_v1(
    request: &NovExecutionRequestV1,
    settled_fee: &NovSettledFeeV1,
    subject_meta: &NovExecutionSubjectMetaV1,
) -> Result<(OpsWirePayload, u64)> {
    let target = execution_target_label_v1(&request.target);
    let plan_id = native_execution_request_plan_id_v1(request, subject_meta);
    let key = sha256_bytes_v1(&[
        b"novovm-native-aoem-semantic-key-v1",
        request.tx_hash.as_slice(),
        target.as_bytes(),
        request.method.as_bytes(),
        subject_meta.account_id.as_bytes(),
    ]);
    let value = sha256_bytes_v1(&[
        b"novovm-native-aoem-semantic-value-v1",
        request.args.as_slice(),
        settled_fee.source_asset.as_bytes(),
        &settled_fee.source_amount.to_le_bytes(),
        &settled_fee.nov_amount.to_le_bytes(),
        subject_meta.execution_policy.as_bytes(),
        subject_meta.key_algo.as_bytes(),
    ]);
    let mut builder = OpsWireV1Builder::new();
    builder.push(OpsWireOp {
        opcode: 2,
        flags: 0,
        reserved: 0,
        key: &key,
        value: &value,
        delta: 0,
        expect_version: None,
        plan_id,
    })?;
    Ok((builder.finish(), plan_id))
}

fn native_aoem_parallelism_meta_v1(
    op_count: usize,
    runtime: Option<&AoemRuntimeConfig>,
) -> (bool, String, usize, u32, usize, usize, String) {
    let concurrent_enabled = native_aoem_concurrent_execution_enabled_v1();
    let hint = AoemHostHint {
        txs: op_count.max(1) as u64,
        batch: op_count.min(u32::MAX as usize).max(1) as u32,
        key_space: op_count.max(1) as u64,
        rw: 1.0,
    };
    let decision = recommend_threads_auto(&hint);
    let recommended_threads = if concurrent_enabled {
        decision.recommended_threads.max(1)
    } else {
        1
    };
    let ingress_workers = runtime
        .and_then(|cfg| cfg.ingress_workers)
        .unwrap_or(recommended_threads.min(u32::MAX as usize) as u32)
        .max(1);
    (
        concurrent_enabled,
        "AOEM algebraic semantic batch ingress; deterministic ledger commit after batch precommit"
            .to_string(),
        recommended_threads,
        ingress_workers,
        decision.hw_threads,
        decision.budget_threads,
        decision.reason.to_string(),
    )
}

fn attach_native_aoem_parallelism_meta_v1(
    meta: &mut NovAoemSemanticIngressMetaV1,
    runtime: Option<&AoemRuntimeConfig>,
) {
    let (
        concurrent_enabled,
        model,
        recommended_threads,
        ingress_workers,
        hw_threads,
        budget_threads,
        reason,
    ) = native_aoem_parallelism_meta_v1(meta.op_count, runtime);
    meta.concurrent_execution_enabled = concurrent_enabled;
    meta.concurrent_execution_model = model;
    meta.batch_size = meta.op_count;
    meta.recommended_threads = recommended_threads;
    meta.ingress_workers = ingress_workers;
    meta.host_hw_threads = hw_threads;
    meta.host_budget_threads = budget_threads;
    meta.parallelism_reason = reason;
}

struct CachedNativeAoemSemanticIngressRuntimeV1 {
    key: String,
    session: AoemExecSession,
}

static NATIVE_AOEM_SEMANTIC_RUNTIME_OPEN_COUNT_V1: AtomicU64 = AtomicU64::new(0);
static NATIVE_AOEM_SEMANTIC_SESSION_CREATED_COUNT_V1: AtomicU64 = AtomicU64::new(0);
static NATIVE_AOEM_SEMANTIC_SESSION_REUSED_COUNT_V1: AtomicU64 = AtomicU64::new(0);

thread_local! {
    static NATIVE_AOEM_SEMANTIC_INGRESS_RUNTIME_V1: RefCell<Option<CachedNativeAoemSemanticIngressRuntimeV1>> = const { RefCell::new(None) };
}

pub fn native_aoem_semantic_ingress_runtime_reuse_counters_v1() -> serde_json::Value {
    serde_json::json!({
        "aoem_runtime_open_count": NATIVE_AOEM_SEMANTIC_RUNTIME_OPEN_COUNT_V1.load(Ordering::Relaxed),
        "aoem_handle_created_count": NATIVE_AOEM_SEMANTIC_SESSION_CREATED_COUNT_V1.load(Ordering::Relaxed),
        "aoem_session_created_count": NATIVE_AOEM_SEMANTIC_SESSION_CREATED_COUNT_V1.load(Ordering::Relaxed),
        "aoem_session_reused_count": NATIVE_AOEM_SEMANTIC_SESSION_REUSED_COUNT_V1.load(Ordering::Relaxed),
        "aoem_worker_pool_created_count": NATIVE_AOEM_SEMANTIC_SESSION_CREATED_COUNT_V1.load(Ordering::Relaxed),
        "tokio_runtime_created_count": 0u64,
        "std_thread_spawn_count": 0u64,
        "spawn_blocking_count": 0u64,
    })
}

fn native_aoem_semantic_ingress_runtime_key_v1(runtime: &AoemRuntimeConfig) -> String {
    let persistence_path = std::env::var("AOEM_PERSISTENCE_PATH").unwrap_or_default();
    format!(
        "{}|variant={}|persist_backend={}|persistence_path={}|ingress_workers={}",
        runtime.dll_path.display(),
        runtime.variant.as_str(),
        runtime.persist_backend,
        persistence_path,
        runtime.ingress_workers.unwrap_or(0)
    )
}

fn with_native_aoem_semantic_ingress_session_v1<T>(
    runtime: &AoemRuntimeConfig,
    f: impl FnOnce(&AoemExecSession) -> Result<T>,
) -> Result<T> {
    let key = native_aoem_semantic_ingress_runtime_key_v1(runtime);
    NATIVE_AOEM_SEMANTIC_INGRESS_RUNTIME_V1.with(|slot| {
        let mut slot = slot.borrow_mut();
        let needs_open = slot
            .as_ref()
            .map(|cached| cached.key != key)
            .unwrap_or(true);
        if needs_open {
            let facade = AoemExecFacade::open_with_runtime(runtime)?;
            if !facade.supports_ops_wire_v1() {
                bail!("ops_wire_v1_unsupported");
            }
            let session = facade.create_session()?;
            NATIVE_AOEM_SEMANTIC_RUNTIME_OPEN_COUNT_V1.fetch_add(1, Ordering::Relaxed);
            NATIVE_AOEM_SEMANTIC_SESSION_CREATED_COUNT_V1.fetch_add(1, Ordering::Relaxed);
            *slot = Some(CachedNativeAoemSemanticIngressRuntimeV1 {
                key: key.clone(),
                session,
            });
        } else {
            NATIVE_AOEM_SEMANTIC_SESSION_REUSED_COUNT_V1.fetch_add(1, Ordering::Relaxed);
        }
        let cached = slot
            .as_ref()
            .context("AOEM semantic ingress runtime cache missing after initialization")?;
        f(&cached.session)
    })
}

#[cfg(test)]
fn reset_native_aoem_semantic_ingress_session_v1() {
    NATIVE_AOEM_SEMANTIC_INGRESS_RUNTIME_V1.with(|slot| {
        *slot.borrow_mut() = None;
    });
}

fn native_aoem_semantic_ingress_error_reason_v1(err: &anyhow::Error) -> String {
    let err_text = err.to_string();
    if err_text.contains("ops_wire_v1_unsupported") {
        "ops_wire_v1_unsupported".to_string()
    } else if err_text.contains("AOEM semantic ingress runtime cache missing") {
        format!("runtime_cache_failed: {err_text}")
    } else if err_text.contains("AOEM handle create failed") {
        format!("session_create_failed: {err_text}")
    } else if err_text.contains("AOEM startup")
        || err_text.contains("load")
        || err_text.contains("DLL")
    {
        format!("runtime_open_failed: {err_text}")
    } else {
        format!("submit_failed: {err_text}")
    }
}

fn base_native_aoem_semantic_ingress_meta_v1(
    enabled: bool,
    required: bool,
    plan_id: u64,
    wire: &OpsWirePayload,
) -> NovAoemSemanticIngressMetaV1 {
    let mut meta = NovAoemSemanticIngressMetaV1 {
        execution_kernel: "AOEM".to_string(),
        semantic_entry: native_aoem_semantic_entry_v1().to_string(),
        algebraic_semantic_entry: true,
        ingress_scope: "single_request".to_string(),
        batch_plan_id: None,
        batch_item_index: None,
        batch_item_count: None,
        concurrent_execution_enabled: false,
        concurrent_execution_model: String::new(),
        batch_mode: wire.op_count > 1,
        batch_size: wire.op_count,
        recommended_threads: 1,
        ingress_workers: 1,
        host_hw_threads: 1,
        host_budget_threads: 1,
        parallelism_reason: String::new(),
        enabled,
        required,
        submitted: false,
        op_count: wire.op_count,
        plan_id,
        wire_digest: to_hex(&sha256_bytes_v1(&[
            b"novovm-native-aoem-semantic-wire-digest-v1",
            wire.bytes.as_slice(),
        ])),
        processed_ops: 0,
        success_ops: 0,
        total_writes: 0,
        semantic_delta_count: 0,
        semantic_delta_digest: String::new(),
        semantic_state_before_digest: String::new(),
        semantic_state_after_digest: String::new(),
        semantic_ledger_sequence: 0,
        semantic_ledger_prev_seal: String::new(),
        semantic_ledger_commit_seal: String::new(),
        return_code_name: String::new(),
        fallback_reason: None,
    };
    attach_native_aoem_parallelism_meta_v1(&mut meta, None);
    meta
}

fn execute_native_request_via_aoem_semantic_ingress_v1(
    request: &NovExecutionRequestV1,
    settled_fee: &NovSettledFeeV1,
    subject_meta: &NovExecutionSubjectMetaV1,
) -> Result<NovAoemSemanticIngressMetaV1> {
    let enabled = native_aoem_semantic_ingress_enabled_v1();
    let required = native_aoem_semantic_ingress_required_v1();
    let (wire, plan_id) =
        build_native_execution_aoem_ops_wire_v1(request, settled_fee, subject_meta)?;
    let mut meta = base_native_aoem_semantic_ingress_meta_v1(enabled, required, plan_id, &wire);
    if !enabled {
        meta.fallback_reason = Some("aoem_semantic_ingress_disabled".to_string());
        return Ok(meta);
    }

    let runtime = match AoemRuntimeConfig::from_env() {
        Ok(runtime) => runtime,
        Err(err) => {
            if required {
                return Err(err).context("aoem semantic ingress runtime config failed");
            }
            meta.fallback_reason = Some(format!("runtime_config_unavailable: {err}"));
            return Ok(meta);
        }
    };
    attach_native_aoem_parallelism_meta_v1(&mut meta, Some(&runtime));
    if !runtime.dll_path.exists() {
        if required {
            bail!(
                "aoem semantic ingress required but AOEM runtime DLL is missing: {}",
                runtime.dll_path.display()
            );
        }
        meta.fallback_reason = Some(format!(
            "runtime_dll_missing: {}",
            runtime.dll_path.display()
        ));
        return Ok(meta);
    }
    let submit_result = with_native_aoem_semantic_ingress_session_v1(&runtime, |session| {
        session.submit_ops_wire(wire.bytes.as_slice())
    });
    match submit_result {
        Ok(output) => {
            meta.submitted = true;
            meta.processed_ops = output.metrics.processed_ops;
            meta.success_ops = output.metrics.success_ops;
            meta.total_writes = output.metrics.total_writes;
            meta.return_code_name = output.metrics.return_code_name;
            Ok(meta)
        }
        Err(err) => {
            if required {
                return Err(err).context("submit AOEM semantic ingress ops-wire failed");
            }
            meta.fallback_reason = Some(native_aoem_semantic_ingress_error_reason_v1(&err));
            Ok(meta)
        }
    }
}

pub fn get_nov_native_aoem_semantic_ingress_status_v1() -> serde_json::Value {
    let enabled = native_aoem_semantic_ingress_enabled_v1();
    let required = native_aoem_semantic_ingress_required_v1();
    let concurrent_enabled = native_aoem_concurrent_execution_enabled_v1();
    let max_batch_size = native_aoem_batch_max_size_v1();
    let (
        _concurrent_meta_enabled,
        concurrency_model,
        recommended_threads,
        mut ingress_workers,
        hw_threads,
        budget_threads,
        parallelism_reason,
    ) = native_aoem_parallelism_meta_v1(max_batch_size, None);
    let mut runtime_dll = serde_json::Value::Null;
    let mut runtime_config_ok = false;
    let mut runtime_dll_exists = false;
    let mut ops_wire_v1_supported = false;
    let mut runtime_error = serde_json::Value::Null;

    match AoemRuntimeConfig::from_env() {
        Ok(runtime) => {
            runtime_config_ok = true;
            runtime_dll = serde_json::Value::String(runtime.dll_path.display().to_string());
            ingress_workers = runtime.ingress_workers.unwrap_or(ingress_workers).max(1);
            runtime_dll_exists = runtime.dll_path.exists();
            if runtime_dll_exists {
                match AoemExecFacade::open_with_runtime(&runtime) {
                    Ok(facade) => {
                        ops_wire_v1_supported = facade.supports_ops_wire_v1();
                    }
                    Err(err) => {
                        runtime_error =
                            serde_json::Value::String(format!("runtime_open_failed: {err}"));
                    }
                }
            }
        }
        Err(err) => {
            runtime_error = serde_json::Value::String(format!("runtime_config_unavailable: {err}"));
        }
    }

    let ready = enabled && runtime_config_ok && runtime_dll_exists && ops_wire_v1_supported;
    serde_json::json!({
        "method": "nov_getAoemSemanticIngressStatus",
        "execution_kernel": "AOEM",
        "semantic_entry": native_aoem_semantic_entry_v1(),
        "algebraic_semantic_entry": true,
        "concurrent_execution_enabled": concurrent_enabled,
        "concurrent_execution_model": concurrency_model,
        "native_batch_entry": "nov_sendRawTransactionBatch",
        "native_execute_batch_alias": "nov_executeBatch",
        "max_batch_size": max_batch_size,
        "recommended_threads": recommended_threads,
        "ingress_workers": ingress_workers,
        "host_hw_threads": hw_threads,
        "host_budget_threads": budget_threads,
        "parallelism_reason": parallelism_reason,
        "enabled": enabled,
        "required": required,
        "fail_closed": enabled && required,
        "ready": ready,
        "runtime_config_ok": runtime_config_ok,
        "runtime_dll": runtime_dll,
        "runtime_dll_exists": runtime_dll_exists,
        "ops_wire_v1_supported": ops_wire_v1_supported,
        "runtime_error": runtime_error,
        "fallback_allowed": enabled && !required,
        "fallback_policy": if enabled && required {
            "fail_closed_on_unavailable"
        } else if enabled {
            "record_fallback_reason_and_continue"
        } else {
            "disabled"
        },
        "product_boundary": "native_asset_execution_must_enter_aoem_algebraic_semantic_ingress_for_production_required_mode",
        "storage_fallback_boundary": "json_store_lock_is_transitional_persistence_guard_not_aoem_concurrency_model",
    })
}

pub fn get_nov_native_execution_store_backend_status_v1(path: Option<&Path>) -> serde_json::Value {
    let store_path = path
        .map(Path::to_path_buf)
        .unwrap_or_else(nov_native_execution_store_path_v1);
    let backend = nov_native_execution_store_backend_v1();
    let rocksdb_path = nov_native_execution_store_rocksdb_path_v1(store_path.as_path());
    serde_json::json!({
        "method": "nov_getNativeExecutionStoreBackendStatus",
        "store_path": store_path.display().to_string(),
        "backend": backend,
        "valid_backend": matches!(
            backend.as_str(),
            NOV_NATIVE_EXECUTION_STORE_BACKEND_JSON_V1
                | NOV_NATIVE_EXECUTION_STORE_BACKEND_ROCKSDB_V1
                | NOV_NATIVE_EXECUTION_STORE_BACKEND_DUAL_V1
        ),
        "json_snapshot_enabled": native_execution_store_backend_writes_json_v1(backend.as_str()),
        "rocksdb_enabled": native_execution_store_backend_writes_rocksdb_v1(backend.as_str()),
        "rocksdb_path": rocksdb_path.display().to_string(),
        "json_snapshot_exists": store_path.exists(),
        "rocksdb_exists": rocksdb_path.exists(),
        "transactional_commit": backend == NOV_NATIVE_EXECUTION_STORE_BACKEND_ROCKSDB_V1
            || backend == NOV_NATIVE_EXECUTION_STORE_BACKEND_DUAL_V1,
        "commit_model": if backend == NOV_NATIVE_EXECUTION_STORE_BACKEND_ROCKSDB_V1 {
            "dirty_sharded_atomic_batch_primary"
        } else if backend == NOV_NATIVE_EXECUTION_STORE_BACKEND_DUAL_V1 {
            "dirty_sharded_atomic_batch_with_json_compat_snapshot"
        } else {
            "legacy_json_snapshot"
        },
        "sharded_keyspaces": [
            "account/{account_id}/asset/{asset_id}",
            "receipt/{tx_hash}",
            "receipt_by_height/{height}/{index}/{tx_hash}",
            "module_state/treasury/{key}",
            "module_state/clearing/{key}",
            "module_state/vault/{key}",
            "module_state/policy/{key}",
            "module_state/governance/{key}",
            "module_state/native_execution/{key}",
            "semantic_head/current",
            "semantic_head/by_height/{height}",
            "snapshot_meta/{height}",
        ],
        "product_boundary": "rocksdb_dirty_sharded_backend_removes_single_json_snapshot_and_module_state_core_as_primary_store_but_ordered_commit_is_still_deterministic",
    })
}

#[derive(Debug, Default)]
struct RollingDigestV1 {
    state: u64,
    count: u64,
}

impl RollingDigestV1 {
    fn update(&mut self, bytes: &[u8]) {
        const FNV_OFFSET: u64 = 0xcbf29ce484222325;
        const FNV_PRIME: u64 = 0x100000001b3;
        if self.count == 0 && self.state == 0 {
            self.state = FNV_OFFSET;
        }
        for byte in bytes {
            self.state ^= u64::from(*byte);
            self.state = self.state.wrapping_mul(FNV_PRIME);
        }
        self.count = self.count.saturating_add(1);
    }

    fn finish_hex(&self) -> String {
        format!("{:016x}:{}", self.state, self.count)
    }
}

pub fn get_nov_native_execution_store_recovery_probe_v1(path: &Path) -> Result<serde_json::Value> {
    let store = load_nov_native_execution_store_v1(path)?;
    let sequence = store.module_state.aoem_semantic_ledger_sequence;
    let head = store.module_state.aoem_semantic_ledger_head.clone();
    let backend = nov_native_execution_store_backend_v1();
    let rocksdb_path = nov_native_execution_store_rocksdb_path_v1(path);
    let include_full_receipt_hashes = bool_env_default_v1(
        "NOVOVM_NATIVE_EXECUTION_RECOVERY_PROBE_INCLUDE_FULL_RECEIPT_HASHES",
        false,
    );
    let receipt_hash_sample_limit = usize_env_default_v1(
        "NOVOVM_NATIVE_EXECUTION_RECOVERY_PROBE_RECEIPT_HASH_SAMPLE_LIMIT",
        8,
    );
    let mut semantic_head_current_recovered = false;
    let mut semantic_head_by_height_recovered = false;
    let mut snapshot_meta_current_recovered = false;
    let mut snapshot_meta_by_height_recovered = false;
    let mut receipt_by_height_count = 0usize;
    let mut receipt_by_height_hashes = BTreeSet::<String>::new();
    let mut receipt_by_height_digest = RollingDigestV1::default();
    let mut receipt_by_height_hash_samples = Vec::<String>::new();
    let mut rocksdb_opened = false;

    let network_checkpoint_uses_rocksdb =
        native_execution_store_backend_reads_rocksdb_v1(backend.as_str());
    if network_checkpoint_uses_rocksdb && rocksdb_path.exists() {
        let db = open_nov_native_execution_store_rocksdb_v1(rocksdb_path.as_path())?;
        rocksdb_opened = true;
        semantic_head_current_recovered = db
            .get(NOV_NATIVE_EXECUTION_STORE_ROCKSDB_KEY_SEMANTIC_HEAD_V1)
            .with_context(|| {
                format!(
                    "read nov native execution recovery semantic_head/current failed: {}",
                    rocksdb_path.display()
                )
            })?
            .as_deref()
            == Some(head.as_bytes());
        semantic_head_by_height_recovered = db
            .get(native_rocksdb_semantic_by_height_key_v1(sequence))
            .with_context(|| {
                format!(
                    "read nov native execution recovery semantic_head/by_height failed: {}",
                    rocksdb_path.display()
                )
            })?
            .as_deref()
            == Some(head.as_bytes());
        snapshot_meta_current_recovered = db
            .get(NOV_NATIVE_EXECUTION_STORE_ROCKSDB_SNAPSHOT_META_CURRENT_V1)
            .with_context(|| {
                format!(
                    "read nov native execution recovery snapshot_meta/current failed: {}",
                    rocksdb_path.display()
                )
            })?
            .is_some();
        snapshot_meta_by_height_recovered = db
            .get(native_rocksdb_snapshot_meta_by_height_key_v1(sequence))
            .with_context(|| {
                format!(
                    "read nov native execution recovery snapshot_meta/by_height failed: {}",
                    rocksdb_path.display()
                )
            })?
            .is_some();
        for item in native_rocksdb_iter_prefix_v1(
            &db,
            NOV_NATIVE_EXECUTION_STORE_ROCKSDB_RECEIPT_BY_HEIGHT_PREFIX_V1,
        ) {
            let (_key, raw) = item.with_context(|| {
                format!(
                    "iterate nov native execution recovery receipt_by_height failed: {}",
                    rocksdb_path.display()
                )
            })?;
            receipt_by_height_count = receipt_by_height_count.saturating_add(1);
            if let Ok(tx_hash) = String::from_utf8(raw.as_ref().to_vec()) {
                receipt_by_height_digest.update(tx_hash.as_bytes());
                if receipt_by_height_hash_samples.len() < receipt_hash_sample_limit {
                    receipt_by_height_hash_samples.push(tx_hash.clone());
                }
                receipt_by_height_hashes.insert(tx_hash);
            }
        }
    }

    let receipt_count = store.receipts.len();
    let materialized_account_count = store.module_state.account_asset_balances.len();
    let materialized_account_asset_count = store
        .module_state
        .account_asset_balances
        .values()
        .map(BTreeMap::len)
        .sum::<usize>();
    let mut receipt_hash_digest = RollingDigestV1::default();
    let mut receipt_hash_samples = Vec::<String>::new();
    let mut receipt_index_missing_count = 0usize;
    let mut receipt_hashes_full = if include_full_receipt_hashes {
        Some(Vec::<String>::with_capacity(receipt_count))
    } else {
        None
    };
    for tx_hash in store.receipts.keys() {
        receipt_hash_digest.update(tx_hash.as_bytes());
        if receipt_hash_samples.len() < receipt_hash_sample_limit {
            receipt_hash_samples.push(tx_hash.clone());
        }
        if !receipt_by_height_hashes.contains(tx_hash) {
            receipt_index_missing_count = receipt_index_missing_count.saturating_add(1);
        }
        if let Some(full) = receipt_hashes_full.as_mut() {
            full.push(tx_hash.clone());
        }
    }
    let receipt_index_recovered = receipt_count > 0
        && receipt_by_height_count >= receipt_count
        && receipt_index_missing_count == 0;
    let materialized_view_rebuilt = sequence > 0
        && !head.is_empty()
        && receipt_count > 0
        && store
            .receipts
            .values()
            .all(|receipt| receipt.aoem_semantic_ingress.is_some());
    let block_ledger_path = nov_native_block_ledger_rocksdb_path_v1(path);
    let block_ledger_status = store
        .authority_chain_id
        .or_else(|| {
            std::env::var(NOV_NATIVE_CHAIN_ID_ENV)
                .ok()
                .and_then(|raw| raw.trim().parse::<u64>().ok())
        })
        .filter(|chain_id| *chain_id > 0)
        .map(|chain_id| {
            NovNativeBlockLedgerV1::open(block_ledger_path.as_path())
                .and_then(|ledger| ledger.status(chain_id))
        })
        .transpose()?;

    Ok(serde_json::json!({
        "method": "nov_getNativeExecutionStoreRecoveryProbe",
        "store_path": path.display().to_string(),
        "network_recovery_checkpoint_mode": if network_checkpoint_uses_rocksdb {
            serde_json::json!("rocksdb")
        } else {
            serde_json::json!("memory")
        },
        "network_recovery_checkpoint_backend": backend,
        "network_recovery_checkpoint_role": "diagnostics_only",
        "network_recovery_checkpoint_is_transaction_truth": false,
        "network_recovery_checkpoint_signoff_scope": "transport_recovery_only",
        "network_transport_completion_source": "novorudp_receiver_done_ack",
        "transaction_execution_authority_source": "aoem_runtime_readback",
        "transaction_finality_source": "not_established_without_consensus_seal",
        "aoem_execution_persistence_owner": "aoem_runtime",
        "aoem_execution_persistence_is_truth": true,
        "rocksdb_path": rocksdb_path.display().to_string(),
        "rocksdb_exists": rocksdb_path.exists(),
        "rocksdb_opened": rocksdb_opened,
        "network_recovery_checkpoint_probe_skipped": !network_checkpoint_uses_rocksdb,
        "network_recovery_checkpoint_probe_skipped_reason": if network_checkpoint_uses_rocksdb {
            serde_json::Value::Null
        } else {
            serde_json::json!("network_recovery_checkpoint_memory_first_backend")
        },
        "semantic_head_current_recovered": semantic_head_current_recovered,
        "semantic_head_by_height_recovered": semantic_head_by_height_recovered,
        "snapshot_meta_current_recovered": snapshot_meta_current_recovered,
        "snapshot_meta_by_height_recovered": snapshot_meta_by_height_recovered,
        "receipt_index_recovered": receipt_index_recovered,
        "receipt_by_height_count": receipt_by_height_count,
        "receipt_by_height_hash_digest": receipt_by_height_digest.finish_hex(),
        "receipt_by_height_hash_samples": receipt_by_height_hash_samples,
        "receipt_count": receipt_count,
        "receipt_hash_digest": receipt_hash_digest.finish_hex(),
        "receipt_hash_samples": receipt_hash_samples.clone(),
        "receipt_hashes_omitted": !include_full_receipt_hashes,
        "receipt_hashes_full_count": if include_full_receipt_hashes { receipt_count } else { 0 },
        "receipt_index_missing_count": receipt_index_missing_count,
        "recovery_probe_materialized_key_count": receipt_hash_sample_limit.min(receipt_count),
        "receipt_hashes": if let Some(full) = receipt_hashes_full {
            serde_json::json!({
                "omitted": false,
                "count": receipt_count,
                "digest": receipt_hash_digest.finish_hex(),
                "samples": receipt_hash_samples.clone(),
                "items": full,
            })
        } else {
            serde_json::json!({
                "omitted": true,
                "count": receipt_count,
                "digest": receipt_hash_digest.finish_hex(),
                "samples": receipt_hash_samples.clone(),
            })
        },
        "materialized_view_rebuilt": materialized_view_rebuilt,
        "materialized_account_count": materialized_account_count,
        "materialized_account_asset_count": materialized_account_asset_count,
        "durable_native_nonce_reservation_count": store
            .module_state
            .native_auth_nonce_reservations
            .len(),
        "durable_native_nonce_identity_count": store
            .module_state
            .native_auth_next_nonces
            .len(),
        "semantic_head": {
            "sequence": sequence,
            "head": head,
        },
        "canonical_body_head_recovery": {
            "supported": true,
            "trust_class": "local_unsealed_execution_candidate",
            "ledger_path": block_ledger_path.display().to_string(),
            "status": block_ledger_status,
            "chain_canonical": false,
            "proof_sealed": false,
            "safe": false,
            "finalized": false,
        },
        "recovery_ok": rocksdb_opened
            && semantic_head_current_recovered
            && semantic_head_by_height_recovered
            && snapshot_meta_current_recovered
            && snapshot_meta_by_height_recovered
            && receipt_index_recovered
            && materialized_view_rebuilt,
    }))
}

fn u128_delta_i128_v1(before: u128, after: u128) -> i128 {
    if after >= before {
        saturating_u128_to_i128_v1(after.saturating_sub(before))
    } else {
        -saturating_u128_to_i128_v1(before.saturating_sub(after))
    }
}

fn push_native_semantic_delta_v1(
    deltas: &mut Vec<serde_json::Value>,
    kind: &str,
    owner: Option<&str>,
    asset: &str,
    before: u128,
    after: u128,
) {
    if before == after {
        return;
    }
    deltas.push(serde_json::json!({
        "kind": kind,
        "owner": owner,
        "asset": normalize_asset_symbol_v1(asset),
        "before": before,
        "after": after,
        "delta": u128_delta_i128_v1(before, after),
    }));
}

fn push_native_json_semantic_delta_v1(
    deltas: &mut Vec<serde_json::Value>,
    kind: &str,
    before: serde_json::Value,
    after: serde_json::Value,
) {
    if before == after {
        return;
    }
    let before_bytes = serde_json::to_vec(&before).unwrap_or_default();
    let after_bytes = serde_json::to_vec(&after).unwrap_or_default();
    deltas.push(serde_json::json!({
        "kind": kind,
        "before_digest": to_hex(&sha256_bytes_v1(&[
            b"novovm-native-aoem-semantic-json-delta-before-v1",
            before_bytes.as_slice(),
        ])),
        "after_digest": to_hex(&sha256_bytes_v1(&[
            b"novovm-native-aoem-semantic-json-delta-after-v1",
            after_bytes.as_slice(),
        ])),
    }));
}

