fn canonical_json_value_wire_v1(value: &serde_json::Value) -> Result<Vec<u8>> {
    fn push_len_v1(out: &mut Vec<u8>, len: usize) -> Result<()> {
        out.extend_from_slice(
            &u64::try_from(len)
                .context("canonical JSON value length exceeds u64")?
                .to_be_bytes(),
        );
        Ok(())
    }

    fn encode_v1(value: &serde_json::Value, out: &mut Vec<u8>) -> Result<()> {
        match value {
            serde_json::Value::Null => out.push(0),
            serde_json::Value::Bool(false) => out.push(1),
            serde_json::Value::Bool(true) => out.push(2),
            serde_json::Value::Number(number) => {
                out.push(3);
                let text = number.to_string();
                push_len_v1(out, text.len())?;
                out.extend_from_slice(text.as_bytes());
            }
            serde_json::Value::String(text) => {
                out.push(4);
                push_len_v1(out, text.len())?;
                out.extend_from_slice(text.as_bytes());
            }
            serde_json::Value::Array(items) => {
                out.push(5);
                push_len_v1(out, items.len())?;
                for item in items {
                    encode_v1(item, out)?;
                }
            }
            serde_json::Value::Object(map) => {
                out.push(6);
                push_len_v1(out, map.len())?;
                let mut keys = map.keys().collect::<Vec<_>>();
                keys.sort_unstable();
                for key in keys {
                    push_len_v1(out, key.len())?;
                    out.extend_from_slice(key.as_bytes());
                    encode_v1(&map[key], out)?;
                }
            }
        }
        Ok(())
    }

    let mut out = Vec::new();
    encode_v1(value, &mut out)?;
    Ok(out)
}

fn full_native_receipt_commitment_v1(receipt: &NovNativeExecutionReceiptV1) -> Result<[u8; 32]> {
    let logs = receipt
        .logs
        .iter()
        .map(|log| {
            Ok(NovConsensusReceiptLogWireV1 {
                module: log.module.as_str(),
                method: log.method.as_str(),
                event: log.event.as_str(),
                canonical_data: canonical_json_value_wire_v1(&log.data)?,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let route_meta = receipt
        .route_meta
        .as_ref()
        .map(|meta| NovConsensusReceiptRouteWireV1 {
            route_id: meta.route_id.as_str(),
            route_source: meta.route_source.as_str(),
            expected_nov_out: meta.expected_nov_out,
            route_fee_ppm: meta.route_fee_ppm,
            selection_reason: meta.selection_reason.as_str(),
            candidate_route_count: meta.candidate_route_count,
        });
    let policy_meta = receipt
        .policy_meta
        .as_ref()
        .map(|meta| NovConsensusReceiptPolicyWireV1 {
            policy_contract_id: meta.policy_contract_id.as_str(),
            policy_version: meta.policy_version,
            policy_source: meta.policy_source.as_str(),
            policy_threshold_state: meta.policy_threshold_state.as_str(),
            policy_constrained_strategy: meta.policy_constrained_strategy.as_str(),
        });
    let aoem_semantic_commit =
        receipt
            .aoem_semantic_commit
            .as_ref()
            .map(|meta| NovConsensusReceiptAoemCommitWireV1 {
                schema: meta.schema.as_str(),
                execution_kernel: meta.execution_kernel.as_str(),
                semantic_entry: meta.semantic_entry.as_str(),
                algebraic_semantic_entry: meta.algebraic_semantic_entry,
                semantic_delta_count: meta.semantic_delta_count as u64,
                semantic_delta_digest: meta.semantic_delta_digest.as_str(),
                state_before_digest: meta.state_before_digest.as_str(),
                state_after_digest: meta.state_after_digest.as_str(),
                sequence: meta.sequence,
                prev_seal: meta.prev_seal.as_str(),
                commit_seal: meta.commit_seal.as_str(),
                source: meta.source.as_str(),
                subject: meta.subject.as_str(),
                action: meta.action.as_str(),
                tx_ref: meta.tx_ref.as_str(),
            });
    let wire = NovConsensusReceiptWireV1 {
        codec: NOVOVM_NATIVE_RECEIPT_ROOT_CODEC_V2,
        tx_hash: receipt.tx_hash.as_str(),
        status: receipt.status,
        target: receipt.target.as_str(),
        module: receipt.module.as_str(),
        method: receipt.method.as_str(),
        account_id: receipt.account_id.as_str(),
        fee_owner_account_id: receipt.fee_owner_account_id.as_str(),
        nonce_owner_account_id: receipt.nonce_owner_account_id.as_str(),
        key_algo: receipt.key_algo.as_str(),
        execution_policy: receipt.execution_policy.as_str(),
        policy_enforced: receipt.policy_enforced,
        policy_rejection_reason: receipt.policy_rejection_reason.as_deref(),
        settled_fee_nov: receipt.settled_fee_nov,
        paid_asset: receipt.paid_asset.as_str(),
        paid_amount: receipt.paid_amount,
        logs,
        failure_reason: receipt.failure_reason.as_deref(),
        fee_contract: receipt.fee_contract.as_str(),
        fee_route: receipt.fee_route.as_str(),
        fee_quote_id: receipt.fee_quote_id.as_str(),
        fee_quote_contract: receipt.fee_quote_contract.as_str(),
        fee_clearing_contract: receipt.fee_clearing_contract.as_str(),
        fee_price_source: receipt.fee_price_source.as_str(),
        fee_quote_required_pay_amount: receipt.fee_quote_required_pay_amount,
        fee_quote_expires_at_unix_ms: receipt.fee_quote_expires_at_unix_ms,
        fee_clearing_route_ref: receipt.fee_clearing_route_ref.as_str(),
        fee_clearing_source: receipt.fee_clearing_source.as_str(),
        fee_clearing_rate_ppm: receipt.fee_clearing_rate_ppm,
        route_meta,
        policy_meta,
        aoem_semantic_commit,
    };
    let encoded = crate::bincode_compat::serialize(&wire)
        .context("encode canonical NOV native receipt wire for block commitment failed")?;
    Ok(sha256_bytes_v1(&[
        b"novovm-full-native-receipt-commitment-v1\0",
        encoded.as_slice(),
    ]))
}

fn nov_native_execution_store_backend_v1() -> String {
    std::env::var(NOV_NATIVE_EXECUTION_STORE_BACKEND_ENV)
        .unwrap_or_else(|_| NOV_NATIVE_EXECUTION_STORE_BACKEND_JSON_V1.to_string())
        .trim()
        .to_ascii_lowercase()
}

fn native_execution_store_backend_reads_rocksdb_v1(backend: &str) -> bool {
    matches!(
        backend,
        NOV_NATIVE_EXECUTION_STORE_BACKEND_ROCKSDB_V1 | NOV_NATIVE_EXECUTION_STORE_BACKEND_DUAL_V1
    )
}

fn native_execution_store_backend_writes_json_v1(backend: &str) -> bool {
    matches!(
        backend,
        NOV_NATIVE_EXECUTION_STORE_BACKEND_JSON_V1 | NOV_NATIVE_EXECUTION_STORE_BACKEND_DUAL_V1
    )
}

fn native_execution_store_backend_writes_rocksdb_v1(backend: &str) -> bool {
    native_execution_store_backend_reads_rocksdb_v1(backend)
}

fn open_nov_native_execution_store_rocksdb_v1(path: &Path) -> Result<RocksDb> {
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent).with_context(|| {
                format!(
                    "create host recovery rocksdb parent dir failed: {}",
                    parent.display()
                )
            })?;
        }
    }
    let mut opts = RocksDbOptions::default();
    opts.create_if_missing(true);
    RocksDb::open(&opts, path)
        .with_context(|| format!("open host recovery rocksdb failed: {}", path.display()))
}

fn rocksdb_property_u64_v1(db: &RocksDb, property: &str) -> Option<u64> {
    db.property_int_value(property).ok().flatten()
}

pub fn get_nov_native_execution_store_rocksdb_memory_probe_v1(path: &Path) -> serde_json::Value {
    let rocksdb_path = nov_native_execution_store_rocksdb_path_v1(path);
    if !rocksdb_path.exists() {
        return serde_json::json!({
            "method": "nov_getNativeExecutionStoreRocksDbMemoryProbe",
            "rocksdb_path": rocksdb_path.display().to_string(),
            "rocksdb_exists": false,
            "rocksdb_opened": false,
            "rocksdb_total_estimated_memory_bytes": 0u64,
            "rocksdb_memory_probe_supported": true,
        });
    }
    let db = match open_nov_native_execution_store_rocksdb_v1(rocksdb_path.as_path()) {
        Ok(db) => db,
        Err(err) => {
            return serde_json::json!({
                "method": "nov_getNativeExecutionStoreRocksDbMemoryProbe",
                "rocksdb_path": rocksdb_path.display().to_string(),
                "rocksdb_exists": true,
                "rocksdb_opened": false,
                "rocksdb_open_error": err.to_string(),
                "rocksdb_total_estimated_memory_bytes": 0u64,
                "rocksdb_memory_probe_supported": false,
            });
        }
    };
    let block_cache = rocksdb_property_u64_v1(&db, "rocksdb.block-cache-usage").unwrap_or(0);
    let block_cache_pinned =
        rocksdb_property_u64_v1(&db, "rocksdb.block-cache-pinned-usage").unwrap_or(0);
    let memtable_current =
        rocksdb_property_u64_v1(&db, "rocksdb.cur-size-all-mem-tables").unwrap_or(0);
    let memtable_total =
        rocksdb_property_u64_v1(&db, "rocksdb.size-all-mem-tables").unwrap_or(memtable_current);
    let table_readers =
        rocksdb_property_u64_v1(&db, "rocksdb.estimate-table-readers-mem").unwrap_or(0);
    let estimate_num_keys = rocksdb_property_u64_v1(&db, "rocksdb.estimate-num-keys").unwrap_or(0);
    let total = block_cache
        .saturating_add(block_cache_pinned)
        .saturating_add(memtable_total)
        .saturating_add(table_readers);
    serde_json::json!({
        "method": "nov_getNativeExecutionStoreRocksDbMemoryProbe",
        "rocksdb_path": rocksdb_path.display().to_string(),
        "rocksdb_exists": true,
        "rocksdb_opened": true,
        "rocksdb_block_cache_estimated_bytes": block_cache,
        "rocksdb_block_cache_pinned_estimated_bytes": block_cache_pinned,
        "rocksdb_memtable_estimated_bytes": memtable_total,
        "rocksdb_current_memtable_estimated_bytes": memtable_current,
        "rocksdb_index_filter_estimated_bytes": table_readers,
        "rocksdb_estimate_num_keys": estimate_num_keys,
        "rocksdb_total_estimated_memory_bytes": total,
        "rocksdb_memory_probe_supported": true,
    })
}

fn native_rocksdb_account_asset_key_v1(account_id: &str, asset: &str) -> Vec<u8> {
    format!(
        "account/{}/asset/{}",
        account_id,
        normalize_asset_symbol_v1(asset)
    )
    .into_bytes()
}

fn native_rocksdb_receipt_key_v1(tx_hash: &str) -> Vec<u8> {
    format!("receipt/{tx_hash}").into_bytes()
}

fn native_rocksdb_receipt_by_height_key_v1(height: u64, index: usize, tx_hash: &str) -> Vec<u8> {
    let mut key = NOV_NATIVE_EXECUTION_STORE_ROCKSDB_RECEIPT_BY_HEIGHT_PREFIX_V1.to_vec();
    key.extend_from_slice(format!("{height:020}/{index:020}/{tx_hash}").as_bytes());
    key
}

fn native_rocksdb_semantic_by_height_key_v1(height: u64) -> Vec<u8> {
    let mut key = NOV_NATIVE_EXECUTION_STORE_ROCKSDB_SEMANTIC_BY_HEIGHT_PREFIX_V1.to_vec();
    key.extend_from_slice(format!("{height:020}").as_bytes());
    key
}

fn native_rocksdb_snapshot_meta_by_height_key_v1(height: u64) -> Vec<u8> {
    let mut key = NOV_NATIVE_EXECUTION_STORE_ROCKSDB_SNAPSHOT_META_PREFIX_V1.to_vec();
    key.extend_from_slice(format!("{height:020}").as_bytes());
    key
}

fn native_rocksdb_key_has_prefix_v1(key: &[u8], prefix: &[u8]) -> bool {
    key.starts_with(prefix)
}

fn native_rocksdb_decode_account_asset_key_v1(key: &[u8]) -> Option<(String, String)> {
    let raw = std::str::from_utf8(key).ok()?;
    let rest = raw.strip_prefix("account/")?;
    let (account, asset) = rest.split_once("/asset/")?;
    if account.is_empty() || asset.is_empty() {
        return None;
    }
    Some((account.to_string(), normalize_asset_symbol_v1(asset)))
}

type NativeRocksDbIterItemV1 = Result<(Box<[u8]>, Box<[u8]>), rocksdb::Error>;

fn native_rocksdb_iter_prefix_v1(db: &RocksDb, prefix: &[u8]) -> Vec<NativeRocksDbIterItemV1> {
    db.iterator(RocksDbIteratorMode::From(prefix, RocksDbDirection::Forward))
        .take_while(|item| {
            item.as_ref()
                .map(|(key, _)| native_rocksdb_key_has_prefix_v1(key.as_ref(), prefix))
                .unwrap_or(true)
        })
        .collect()
}

fn native_rocksdb_snapshot_meta_v1(
    store: &NovNativeExecutionStoreV1,
) -> NovNativeExecutionStoreSnapshotMetaV1 {
    let account_asset_count = store
        .module_state
        .account_asset_balances
        .values()
        .map(BTreeMap::len)
        .sum();
    NovNativeExecutionStoreSnapshotMetaV1 {
        schema: "novovm-native-execution-store-snapshot-meta/v1".to_string(),
        store_schema: store.schema.clone(),
        backend_schema: "rocksdb_sharded_commit/v1".to_string(),
        authority_chain_id: store.authority_chain_id,
        authority_namespace_digest: store.authority_namespace_digest.clone(),
        last_updated_unix_ms: store.last_updated_unix_ms,
        receipt_count: store.receipts.len(),
        account_count: store.module_state.account_asset_balances.len(),
        account_asset_count,
        semantic_ledger_sequence: store.module_state.aoem_semantic_ledger_sequence,
        semantic_ledger_head: store.module_state.aoem_semantic_ledger_head.clone(),
    }
}

