fn native_pending_execution_eligible_stage_v1(
    stage: NetworkRuntimeNativePendingTxLifecycleStageV1,
) -> bool {
    matches!(
        stage,
        NetworkRuntimeNativePendingTxLifecycleStageV1::Seen
            | NetworkRuntimeNativePendingTxLifecycleStageV1::Pending
            | NetworkRuntimeNativePendingTxLifecycleStageV1::Propagated
            | NetworkRuntimeNativePendingTxLifecycleStageV1::ReorgedBackToPending
    )
}

fn full_native_receipt_commitments_for_prepared_v1(
    prepared: &NovNativePreparedBlockV1,
    envelope: &NovAoemOwnedNativeStateEnvelopeV1,
) -> Result<Vec<[u8; 32]>> {
    if envelope.batch_result.per_tx_receipts.len() != prepared.tx_hashes.len() {
        bail!("AOEM block recovery receipt count does not match prepared candidate");
    }
    let mut commitments = Vec::with_capacity(prepared.tx_hashes.len());
    for (index, (expected_hash, aoem_receipt)) in prepared
        .tx_hashes
        .iter()
        .zip(envelope.batch_result.per_tx_receipts.iter())
        .enumerate()
    {
        let result_hash = parse_fixed_hex_32_v1(
            aoem_receipt.tx_hash.as_str(),
            "AOEM block result transaction hash",
        )?;
        if result_hash != *expected_hash {
            bail!(
                "AOEM block result transaction order mismatch at index {}",
                index
            );
        }
        let receipt_key = normalize_tx_hash_hex_v1(aoem_receipt.tx_hash.as_str());
        let receipt = envelope
            .store
            .receipts
            .get(receipt_key.as_str())
            .with_context(|| {
                format!(
                    "AOEM-owned state is missing full receipt for prepared transaction {}",
                    aoem_receipt.tx_hash
                )
            })?;
        if receipt.status != aoem_receipt.status_ok {
            bail!("AOEM batch receipt status differs from full native receipt");
        }
        commitments.push(full_native_receipt_commitment_v1(receipt)?);
    }
    Ok(commitments)
}

fn commit_prepared_native_block_from_aoem_v1(
    params: &serde_json::Value,
    chain_id: u64,
    ledger_path: &Path,
) -> Result<NovNativeDurableBlockV1> {
    let ledger = NovNativeBlockLedgerV1::open(ledger_path)?;
    let prepared = ledger
        .load_prepared(chain_id)?
        .context("AOEM-owned batch completed without a durable prepared block candidate")?;
    let envelope = load_validated_native_state_envelope_from_aoem_owner_v1(params, chain_id)?
        .context("AOEM-owned block commit envelope is missing")?;
    if !envelope.production_accepted {
        bail!("AOEM-owned block commit envelope is not production accepted");
    }
    if envelope.state_root_codec != NOVOVM_NATIVE_STATE_ROOT_CODEC_V3
        || envelope.receipt_root_codec != NOVOVM_NATIVE_RECEIPT_ROOT_CODEC_V2
    {
        bail!(
            "AOEM-owned block commit requires consensus state/receipt codecs: state={} receipt={}",
            envelope.state_root_codec,
            envelope.receipt_root_codec
        );
    }
    if prepared.expected_aoem_batch_id.as_deref() != Some(envelope.batch_result.batch_id.as_str()) {
        bail!("AOEM-owned block result does not match the prepared context-bound batch id");
    }
    if prepared.expected_aoem_output_commitment.as_deref()
        != Some(envelope.expected_output_commitment.as_str())
    {
        bail!("AOEM-owned block result does not match the prepared expected output commitment");
    }
    validate_durable_production_acceptance_v1(&prepared, &envelope)
        .context("AOEM-owned block commit production gate revalidation failed")?;
    let receipt_commitments =
        full_native_receipt_commitments_for_prepared_v1(&prepared, &envelope)?;
    let evidence_commitment = native_aoem_execution_evidence_commitment_v1(&envelope.batch_result)?;
    ledger.commit(
        &prepared,
        NovNativeBlockCommitInputV1 {
            post_state_root: parse_fixed_hex_32_v1(
                envelope.state_root.as_str(),
                "AOEM post_state_root",
            )?,
            cumulative_receipt_root: parse_fixed_hex_32_v1(
                envelope.receipt_root.as_str(),
                "AOEM cumulative_receipt_root",
            )?,
            per_block_receipt_commitments: receipt_commitments,
            aoem_batch_id: envelope.batch_result.batch_id.clone(),
            aoem_batch_result_id: envelope.batch_result.batch_result_id.clone(),
            aoem_evidence_commitment: parse_fixed_hex_32_v1(
                evidence_commitment.as_str(),
                "AOEM execution_evidence_commitment",
            )?,
            state_version: envelope.batch_result.snapshot_metadata.state_version,
        },
    )
}

fn project_executed_native_pending_batch_to_unsealed_v1(
    params: &serde_json::Value,
    chain_id: u64,
    tx_hashes: &[[u8; 32]],
    raw_txs: &[Vec<u8>],
    batch_result: &serde_json::Value,
) -> Result<serde_json::Value> {
    if tx_hashes.is_empty() {
        return Ok(serde_json::json!({
            "enabled": false,
            "reason": "empty_executed_native_pending_batch",
        }));
    }
    let production_candidate = batch_result
        .get("aoem_native_tx_batch_production_candidate_enabled")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
        || batch_result
            .get("durable_block_candidate_committed")
            .is_some_and(serde_json::Value::is_object);
    if production_candidate {
        let store_path = resolve_native_execution_store_path_from_params_v1(params)
            .unwrap_or_else(nov_native_execution_store_path_v1);
        let ledger_path = nov_native_block_ledger_rocksdb_path_v1(store_path.as_path());
        let durable: NovNativeDurableBlockV1 = serde_json::from_value(
            batch_result
                .get("durable_block_candidate_committed")
                .filter(|value| value.is_object())
                .cloned()
                .context("accepted AOEM production batch is missing its durable block commit")?,
        )
        .context("decode internally committed durable NOV block")?;
        if durable.body.tx_hashes != tx_hashes || durable.body.raw_txs != raw_txs {
            bail!("durable NOV block readback differs from executed pending batch");
        }
        for tx_hash in durable.body.tx_hashes.iter().copied() {
            observe_network_runtime_native_pending_tx_included_unsealed_v1(
                chain_id,
                tx_hash,
                durable.header.height,
                durable.header.block_hash,
                u128::from(durable.header.timestamp_unix_ms),
            );
        }
        return Ok(serde_json::json!({
            "enabled": true,
            "projection": "aoem_verified_native_execution_to_durable_unsealed_candidate_v1",
            "ledger_path": ledger_path.display().to_string(),
            "block_number": durable.header.height,
            "block_hash": to_hex_prefixed_v1(&durable.header.block_hash),
            "parent_block_hash": to_hex_prefixed_v1(&durable.header.parent_block_hash),
            "pre_state_root": to_hex_prefixed_v1(&durable.header.pre_state_root),
            "post_state_root": to_hex_prefixed_v1(&durable.header.post_state_root),
            "transactions_root": to_hex_prefixed_v1(&durable.header.ordered_tx_root),
            "block_receipt_root": to_hex_prefixed_v1(&durable.header.block_receipt_root),
            "cumulative_receipt_root": to_hex_prefixed_v1(&durable.header.cumulative_receipt_root),
            "execution_evidence_commitment": to_hex_prefixed_v1(&durable.header.aoem_evidence_commitment),
            "aoem_batch_id": durable.header.aoem_batch_id,
            "aoem_batch_result_id": durable.header.aoem_batch_result_id,
            "tx_count": durable.header.tx_count,
            "local_execution_canonical": true,
            "included_canonical": false,
            "chain_canonical": false,
            "proof_sealed": false,
            "safe": false,
            "finalized": false,
            "seal_status": "unsealed_execution_candidate",
        }));
    }

    // Compatibility-only projection. It deliberately remains unsealed and is
    // never inserted into the shared network head/header/body views. Those
    // views are consumed by status and sync protocols and therefore belong
    // exclusively to proof-sealed consensus state.
    let now_ms = now_unix_millis_v1();
    let previous_head = get_network_runtime_native_head_snapshot_v1(chain_id);
    let block_number = previous_head
        .as_ref()
        .map(|head| head.block_number.saturating_add(1))
        .unwrap_or(1);
    let parent_block_hash = previous_head
        .as_ref()
        .map(|head| head.block_hash)
        .unwrap_or([0u8; 32]);
    let mut block_hash_parts = Vec::<&[u8]>::with_capacity(tx_hashes.len().saturating_add(4));
    let chain_id_bytes = chain_id.to_be_bytes();
    let block_number_bytes = block_number.to_be_bytes();
    block_hash_parts.push(b"novovm-native-legacy-unsealed-candidate-v1");
    block_hash_parts.push(&chain_id_bytes);
    block_hash_parts.push(&block_number_bytes);
    block_hash_parts.push(parent_block_hash.as_slice());
    for tx_hash in tx_hashes {
        block_hash_parts.push(tx_hash.as_slice());
    }
    let block_hash = sha256_bytes_v1(block_hash_parts.as_slice());
    for tx_hash in tx_hashes.iter().copied() {
        observe_network_runtime_native_pending_tx_included_unsealed_v1(
            chain_id,
            tx_hash,
            block_number,
            block_hash,
            now_ms,
        );
    }
    Ok(serde_json::json!({
        "enabled": true,
        "projection": "legacy_native_execution_to_isolated_volatile_unsealed_candidate",
        "block_number": block_number,
        "block_hash": to_hex_prefixed_v1(&block_hash),
        "parent_block_hash": to_hex_prefixed_v1(&parent_block_hash),
        "tx_count": tx_hashes.len(),
        "local_execution_canonical": false,
        "local_execution_ordered": true,
        "included_canonical": false,
        "chain_canonical": false,
        "proof_sealed": false,
        "safe": false,
        "finalized": false,
    }))
}

#[derive(Debug, Clone, Copy, Default)]
struct FinalMissingBatchBlockedInputsV1 {
    candidate_count: u64,
    actual_batch_count: u64,
    payload_available_count: u64,
    selected_count: u64,
    raw_txs_push_success_count: u64,
    payload_missing_count: u64,
    tx_hash_mapping_missing_count: u64,
    raw_tx_build_error_count: u64,
    stage_filter_count: u64,
    scan_limit_count: u64,
    batch_limit_count: u64,
    batch_not_full_count: u64,
    payload_available_not_selected_count: u64,
    selected_not_pushed_count: u64,
    raw_txs_nonempty_not_submitted_count: u64,
    no_tick_executed_count: u64,
    classification_path_not_reached_count: u64,
}

fn final_missing_batch_blocked_reason_v1(inputs: FinalMissingBatchBlockedInputsV1) -> &'static str {
    if inputs.candidate_count == 0 || inputs.actual_batch_count > 0 {
        ""
    } else if inputs.payload_missing_count > 0 {
        "payload_missing"
    } else if inputs.tx_hash_mapping_missing_count > 0 {
        "tx_hash_mapping_missing"
    } else if inputs.raw_tx_build_error_count > 0 {
        "raw_tx_build_error"
    } else if inputs.stage_filter_count > 0 {
        "stage_filter"
    } else if inputs.scan_limit_count > 0 {
        "scan_limit"
    } else if inputs.batch_limit_count > 0 {
        "batch_limit"
    } else if inputs.batch_not_full_count > 0 {
        "batch_not_full"
    } else if inputs.payload_available_not_selected_count > 0 {
        "payload_available_but_not_selected"
    } else if inputs.selected_not_pushed_count > 0 {
        "selected_but_not_pushed_to_raw_txs"
    } else if inputs.raw_txs_nonempty_not_submitted_count > 0 {
        "raw_txs_nonempty_but_not_submitted"
    } else if inputs.payload_available_count > 0
        && inputs.selected_count == 0
        && inputs.raw_txs_push_success_count == 0
    {
        "payload_available_but_not_selected"
    } else if inputs.selected_count > 0 && inputs.raw_txs_push_success_count == 0 {
        "selected_but_not_pushed_to_raw_txs"
    } else if inputs.payload_available_count > 0 {
        "payload_available_definition_not_raw_tx_buildable"
    } else if inputs.classification_path_not_reached_count > 0 {
        "classification_path_not_reached"
    } else if inputs.no_tick_executed_count > 0 {
        "no_tick_executed"
    } else {
        "unknown_invariant_violation"
    }
}

fn sequence_ranges_sample_json_v1(
    sequences: &BTreeSet<u64>,
    max_ranges: usize,
) -> serde_json::Value {
    let mut ranges = Vec::<serde_json::Value>::new();
    let mut iter = sequences.iter().copied();
    let Some(mut start) = iter.next() else {
        return serde_json::Value::Array(ranges);
    };
    let mut end = start;
    for sequence in iter {
        if sequence == end.saturating_add(1) {
            end = sequence;
            continue;
        }
        ranges.push(serde_json::json!({
            "start": start,
            "end": end,
            "count": end.saturating_sub(start).saturating_add(1),
        }));
        if ranges.len() >= max_ranges {
            return serde_json::Value::Array(ranges);
        }
        start = sequence;
        end = sequence;
    }
    ranges.push(serde_json::json!({
        "start": start,
        "end": end,
        "count": end.saturating_sub(start).saturating_add(1),
    }));
    serde_json::Value::Array(ranges)
}

fn novorudp_trace_sample_limit_v1() -> usize {
    std::env::var("NOVOVM_NOVORUDP_TRACE_SAMPLE_LIMIT")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(64)
        .min(512)
}

struct NovorudpTraceStagesV1<'a> {
    candidate_sequences: &'a BTreeSet<u64>,
    payload_available_sequences: &'a BTreeSet<u64>,
    selected_sequences: &'a BTreeSet<u64>,
    raw_txs_pushed_sequences: &'a BTreeSet<u64>,
    actual_batch_sequences: &'a BTreeSet<u64>,
    receipt_sequences: &'a BTreeSet<u64>,
    canonical_sequences: &'a BTreeSet<u64>,
    durable_missing_closed_sequences: &'a BTreeSet<u64>,
}

struct NovorudpSequenceLifecycleTraceInputV1<'a> {
    summary: &'a novovm_network::NetworkRuntimeNativePendingTxSummaryV1,
    repair_final_missing_sequence_start: Option<u64>,
    stages: NovorudpTraceStagesV1<'a>,
    tx_hash_by_sequence: &'a BTreeMap<u64, String>,
    blocked_reason: &'a str,
}

fn novorudp_trace_sequence_entry_v1(
    sequence: u64,
    tx_hash: Option<&String>,
    stages: NovorudpTraceStagesV1<'_>,
    blocked_reason: &str,
) -> serde_json::Value {
    let candidate_created = stages.candidate_sequences.contains(&sequence);
    let payload_available = stages.payload_available_sequences.contains(&sequence);
    let selected = stages.selected_sequences.contains(&sequence);
    let raw_txs_push_success = stages.raw_txs_pushed_sequences.contains(&sequence);
    let actual_batch_included = stages.actual_batch_sequences.contains(&sequence);
    let receipt_written = stages.receipt_sequences.contains(&sequence);
    let canonical_included = stages.canonical_sequences.contains(&sequence);
    let durable_missing_closed = stages.durable_missing_closed_sequences.contains(&sequence);
    let first_missing_stage = if !candidate_created {
        "candidate_created"
    } else if !payload_available {
        "payload_available"
    } else if !selected {
        "selected"
    } else if !raw_txs_push_success {
        "raw_txs_push_success"
    } else if !actual_batch_included {
        "actual_batch_included"
    } else if !receipt_written {
        "receipt_written"
    } else if !canonical_included {
        "canonical_included"
    } else if !durable_missing_closed {
        "durable_missing_closed"
    } else {
        ""
    };
    let sequence_blocked_reason = match first_missing_stage {
        "selected" if !blocked_reason.is_empty() => blocked_reason,
        "raw_txs_push_success" => "selected_but_not_pushed_to_raw_txs",
        "actual_batch_included" => "pushed_not_batched",
        "receipt_written" => "batched_not_receipted",
        "canonical_included" => "receipt_not_canonical",
        "durable_missing_closed" => "canonical_not_closed",
        _ => "",
    };
    serde_json::json!({
        "sequence": sequence,
        "tx_hash": tx_hash.cloned(),
        "packet_received": candidate_created || payload_available,
        "repair_received": candidate_created || payload_available,
        "accepted": candidate_created || payload_available,
        "payload_retained": payload_available,
        "payload_available": payload_available,
        "candidate_created": candidate_created,
        "candidate_source": if candidate_created { "ledger_final_missing" } else { "" },
        "selected": selected,
        "selected_reason": if selected { "final_missing_payload_available" } else { "" },
        "raw_txs_push_attempted": selected,
        "raw_txs_push_success": raw_txs_push_success,
        "actual_batch_included": actual_batch_included,
        "aoem_executed": actual_batch_included,
        "receipt_written": receipt_written,
        "canonical_included": canonical_included,
        "durable_missing_closed": durable_missing_closed,
        "blocked_reason": sequence_blocked_reason,
        "first_missing_stage": first_missing_stage,
    })
}

fn novorudp_trace_first_divergence_stage_v1(
    payload_available_sequences: &BTreeSet<u64>,
    selected_sequences: &BTreeSet<u64>,
    raw_txs_pushed_sequences: &BTreeSet<u64>,
    actual_batch_sequences: &BTreeSet<u64>,
    receipt_sequences: &BTreeSet<u64>,
    canonical_sequences: &BTreeSet<u64>,
    durable_missing_closed_sequences: &BTreeSet<u64>,
) -> (&'static str, Option<u64>) {
    if let Some(sequence) = payload_available_sequences
        .difference(selected_sequences)
        .next()
        .copied()
    {
        return ("payload_available_to_selected", Some(sequence));
    }
    if let Some(sequence) = selected_sequences
        .difference(raw_txs_pushed_sequences)
        .next()
        .copied()
    {
        return ("selected_to_raw_txs_push", Some(sequence));
    }
    if let Some(sequence) = raw_txs_pushed_sequences
        .difference(actual_batch_sequences)
        .next()
        .copied()
    {
        return ("raw_txs_push_to_actual_batch", Some(sequence));
    }
    if let Some(sequence) = actual_batch_sequences
        .difference(receipt_sequences)
        .next()
        .copied()
    {
        return ("actual_batch_to_receipt_written", Some(sequence));
    }
    if let Some(sequence) = receipt_sequences
        .difference(canonical_sequences)
        .next()
        .copied()
    {
        return ("receipt_written_to_canonical_included", Some(sequence));
    }
    if let Some(sequence) = canonical_sequences
        .difference(durable_missing_closed_sequences)
        .next()
        .copied()
    {
        return (
            "canonical_included_to_durable_missing_closed",
            Some(sequence),
        );
    }
    ("", None)
}

fn novorudp_sequence_lifecycle_trace_diff_v1(
    input: NovorudpSequenceLifecycleTraceInputV1<'_>,
) -> serde_json::Value {
    let NovorudpSequenceLifecycleTraceInputV1 {
        summary,
        repair_final_missing_sequence_start,
        stages,
        tx_hash_by_sequence,
        blocked_reason,
    } = input;
    let sample_limit = novorudp_trace_sample_limit_v1();
    let completed_count = summary.ledger_completed_count;
    let success_sample_count = sample_limit.min(16) as u64;
    let success_start = completed_count.saturating_sub(success_sample_count);
    let mut success_sequences = Vec::<serde_json::Value>::new();
    let mut success_trace_set = BTreeSet::<u64>::new();
    for sequence in success_start..completed_count {
        success_trace_set.insert(sequence);
    }
    for sequence in success_trace_set.iter().copied() {
        let mut closed = BTreeSet::new();
        closed.insert(sequence);
        success_sequences.push(novorudp_trace_sequence_entry_v1(
            sequence,
            tx_hash_by_sequence.get(&sequence),
            NovorudpTraceStagesV1 {
                candidate_sequences: &closed,
                payload_available_sequences: &closed,
                selected_sequences: &closed,
                raw_txs_pushed_sequences: &closed,
                actual_batch_sequences: &closed,
                receipt_sequences: &closed,
                canonical_sequences: &closed,
                durable_missing_closed_sequences: &closed,
            },
            "",
        ));
    }

    let failed_start = std::env::var("NOVOVM_NOVORUDP_TRACE_SEQUENCE_START")
        .ok()
        .and_then(|value| value.parse::<u64>().ok())
        .or(repair_final_missing_sequence_start)
        .unwrap_or(completed_count);
    let default_failed_end = summary.ledger_expected_range_end.unwrap_or_else(|| {
        failed_start
            .saturating_add(sample_limit as u64)
            .saturating_sub(1)
    });
    let failed_end = std::env::var("NOVOVM_NOVORUDP_TRACE_SEQUENCE_END")
        .ok()
        .and_then(|value| value.parse::<u64>().ok())
        .unwrap_or(default_failed_end);
    let mut failed_trace_set = BTreeSet::<u64>::new();
    for sequence in failed_start..=failed_end {
        failed_trace_set.insert(sequence);
        if failed_trace_set.len() >= sample_limit {
            break;
        }
    }
    failed_trace_set.extend(
        stages
            .candidate_sequences
            .iter()
            .copied()
            .take(sample_limit),
    );
    failed_trace_set.extend(
        stages
            .payload_available_sequences
            .iter()
            .copied()
            .take(sample_limit),
    );
    failed_trace_set.extend(stages.selected_sequences.iter().copied().take(sample_limit));
    while failed_trace_set.len() > sample_limit {
        let Some(last) = failed_trace_set.iter().next_back().copied() else {
            break;
        };
        failed_trace_set.remove(&last);
    }
    let mut failed_sequences = Vec::<serde_json::Value>::new();
    for sequence in failed_trace_set.iter().copied() {
        failed_sequences.push(novorudp_trace_sequence_entry_v1(
            sequence,
            tx_hash_by_sequence.get(&sequence),
            NovorudpTraceStagesV1 {
                candidate_sequences: stages.candidate_sequences,
                payload_available_sequences: stages.payload_available_sequences,
                selected_sequences: stages.selected_sequences,
                raw_txs_pushed_sequences: stages.raw_txs_pushed_sequences,
                actual_batch_sequences: stages.actual_batch_sequences,
                receipt_sequences: stages.receipt_sequences,
                canonical_sequences: stages.canonical_sequences,
                durable_missing_closed_sequences: stages.durable_missing_closed_sequences,
            },
            blocked_reason,
        ));
    }
    let (first_divergence_stage, first_divergence_sequence) =
        novorudp_trace_first_divergence_stage_v1(
            stages.payload_available_sequences,
            stages.selected_sequences,
            stages.raw_txs_pushed_sequences,
            stages.actual_batch_sequences,
            stages.receipt_sequences,
            stages.canonical_sequences,
            stages.durable_missing_closed_sequences,
        );
    serde_json::json!({
        "novorudp_trace_enabled": true,
        "trace_success_sequences_sample": success_sequences,
        "trace_failed_sequences_sample": failed_sequences,
        "trace_first_divergence_stage": first_divergence_stage,
        "trace_first_divergence_sequence": first_divergence_sequence,
        "trace_success_vs_failed_diff_summary": {
            "completed_sample_count": success_trace_set.len(),
            "failed_sample_count": failed_trace_set.len(),
            "first_divergence_stage": first_divergence_stage,
            "first_divergence_sequence": first_divergence_sequence,
        },
        "trace_candidate_payload_available_not_selected_sequences":
            stages.payload_available_sequences.difference(stages.selected_sequences).copied().take(sample_limit).collect::<Vec<_>>(),
        "trace_selected_not_pushed_sequences":
            stages.selected_sequences.difference(stages.raw_txs_pushed_sequences).copied().take(sample_limit).collect::<Vec<_>>(),
        "trace_pushed_not_batched_sequences":
            stages.raw_txs_pushed_sequences.difference(stages.actual_batch_sequences).copied().take(sample_limit).collect::<Vec<_>>(),
        "trace_batched_not_receipted_sequences":
            stages.actual_batch_sequences.difference(stages.receipt_sequences).copied().take(sample_limit).collect::<Vec<_>>(),
    })
}

fn insert_novorudp_sequence_lifecycle_trace_fields_v1(
    report: &mut serde_json::Map<String, serde_json::Value>,
    trace: &serde_json::Value,
) {
    for key in [
        "novorudp_trace_enabled",
        "trace_success_sequences_sample",
        "trace_failed_sequences_sample",
        "trace_first_divergence_stage",
        "trace_first_divergence_sequence",
        "trace_success_vs_failed_diff_summary",
        "trace_candidate_payload_available_not_selected_sequences",
        "trace_selected_not_pushed_sequences",
        "trace_pushed_not_batched_sequences",
        "trace_batched_not_receipted_sequences",
    ] {
        report.insert(
            key.to_string(),
            trace.get(key).cloned().unwrap_or(serde_json::Value::Null),
        );
    }
}

