    #[test]
    fn execute_pending_promotes_aoem_owned_fields_from_raw_batch_result() {
        with_env_override_v1(
            NOV_NATIVE_AOEM_SEMANTIC_INGRESS_ENABLED_ENV,
            "false",
            || {
                with_test_native_execution_store_path_v1(|path| {
                    with_test_native_aoem_persist_runtime_v1(path.as_path(), |aoem_path| {
                        let state_namespace = aoem_path.to_string_lossy();
                        let chain_id = 88_139_002u64;
                        for sequence in 0..2 {
                            let _ = ingest_test_native_repair_payload_v1(
                                chain_id,
                                sequence,
                                &format!("acct-promote-aoem-owned-{sequence}"),
                                5,
                            );
                        }

                        let out = run_nov_execute_pending_native_tx_batch_from_params_v1(
                            &serde_json::json!({
                                "chain_id": chain_id,
                                "limit": 2,
                                "scan_limit": 2,
                                "repair_final_missing_sequence_start": 0,
                                "native_execution_store_path": path,
                                "aoem_state_namespace": state_namespace,
                                "aoem_owned_gate_config": {
                                    "production_candidate": true,
                                    "shadow": true,
                                    "compare": true,
                                    "source": "receiver_child_runtime"
                                }
                            }),
                        )
                        .expect("execute-pending should promote AOEM-owned fields");

                        assert_eq!(out["executed"].as_bool(), Some(true));
                        assert_eq!(
                            out["tx_ingress_aoem_gate_config_source"].as_str(),
                            Some("receiver_child_runtime")
                        );
                        assert_eq!(
                            out["tx_ingress_aoem_gate_config_production_candidate"].as_bool(),
                            Some(true)
                        );
                        assert_eq!(
                            out["tx_ingress_selected_path"].as_str(),
                            Some("aoem_runtime_owned_state_persistence")
                        );
                        assert_eq!(
                            out["tx_ingress_production_target"].as_str(),
                            Some("aoem_runtime_owned_state_persistence")
                        );
                        assert_eq!(out["aoem_owned_regression_signable"].as_bool(), Some(true));
                        assert_eq!(
                            out["batch_result"]["tx_ingress_selected_path"].as_str(),
                            Some("aoem_runtime_owned_state_persistence")
                        );
                        assert_eq!(
                            out["canonical_projection"]["projection"].as_str(),
                            Some("aoem_verified_native_execution_to_durable_unsealed_candidate_v1")
                        );
                        assert_eq!(
                            out["canonical_projection"]["proof_sealed"].as_bool(),
                            Some(false)
                        );
                        assert_eq!(out["canonical_projection"]["safe"].as_bool(), Some(false));
                        assert_eq!(
                            out["canonical_projection"]["finalized"].as_bool(),
                            Some(false)
                        );
                        let ledger_path = nov_native_block_ledger_rocksdb_path_v1(path.as_path());
                        let ledger = NovNativeBlockLedgerV1::open(ledger_path.as_path())
                            .expect("durable block ledger should reopen");
                        let head = ledger
                            .load_head(chain_id)
                            .expect("durable head should load")
                            .expect("durable head should exist");
                        assert_eq!(head.height, 1);
                        assert!(!head.proof_sealed);
                        assert!(!head.safe);
                        assert!(!head.finalized);
                        let block = ledger
                            .load_by_height(chain_id, 1)
                            .expect("durable block should load")
                            .expect("durable block should exist");
                        assert_eq!(block.body.tx_hashes.len(), 2);
                        assert_eq!(block.header.post_state_root, head.post_state_root);
                        assert_ne!(block.header.post_state_root, [0u8; 32]);
                        assert_ne!(block.header.block_receipt_root, [0u8; 32]);
                        drop(ledger);
                        let query_base = serde_json::json!({
                            "chain_id": chain_id,
                            "native_execution_store_path": path,
                        });
                        let status = run_nov_native_block_ledger_query_internal_v1(
                            "nov_getNativeBlockLedgerStatus",
                            &query_base,
                            true,
                            None,
                        )
                        .expect("block ledger status query should succeed");
                        assert_eq!(status["status"]["head"]["height"].as_u64(), Some(1));
                        let by_height = run_nov_native_block_ledger_query_internal_v1(
                            "nov_getNativeBlockByNumber",
                            &serde_json::json!({
                                "chain_id": chain_id,
                                "native_execution_store_path": path,
                                "block_number": 1,
                            }),
                            true,
                            None,
                        )
                        .expect("block by height query should succeed");
                        assert_eq!(by_height["found"].as_bool(), Some(true));
                        let candidates_by_height = run_nov_native_block_ledger_query_internal_v1(
                            "nov_getNativeBlockCandidatesByNumber",
                            &serde_json::json!({
                                "chain_id": chain_id,
                                "native_execution_store_path": path,
                                "block_number": 1,
                            }),
                            true,
                            None,
                        )
                        .expect("block candidates by height query should succeed");
                        assert_eq!(candidates_by_height["found"].as_bool(), Some(true));
                        assert_eq!(
                            candidates_by_height["trust_class"].as_str(),
                            Some("unsealed_candidate_graph")
                        );
                        assert_eq!(
                            candidates_by_height["candidates"].as_array().map(Vec::len),
                            Some(1)
                        );
                        assert_eq!(
                            candidates_by_height["candidates"][0]["height"].as_u64(),
                            Some(1)
                        );
                        let candidate_by_hash = run_nov_native_block_ledger_query_internal_v1(
                            "nov_getNativeBlockCandidateByHash",
                            &serde_json::json!({
                                "chain_id": chain_id,
                                "native_execution_store_path": path,
                                "block_hash": to_hex_prefixed_v1(&block.header.block_hash),
                            }),
                            true,
                            None,
                        )
                        .expect("block candidate by hash query should succeed");
                        assert_eq!(candidate_by_hash["found"].as_bool(), Some(true));
                        assert_eq!(
                            candidate_by_hash["candidate"]["execution_selected_local"].as_bool(),
                            Some(true)
                        );
                        assert_eq!(
                            candidate_by_hash["artifact_header_canonical_local_scope"].as_str(),
                            Some("producer_local_claim_not_receiver_selection")
                        );
                        assert_eq!(
                            candidate_by_hash["block"]["header"]["height"].as_u64(),
                            Some(1)
                        );
                        let candidate_children = run_nov_native_block_ledger_query_internal_v1(
                            "nov_getNativeBlockCandidateChildren",
                            &serde_json::json!({
                                "chain_id": chain_id,
                                "native_execution_store_path": path,
                                "parent_block_hash": to_hex_prefixed_v1(&[0u8; 32]),
                            }),
                            true,
                            None,
                        )
                        .expect("native candidate children query should succeed");
                        assert_eq!(candidate_children["found"].as_bool(), Some(true));
                        assert_eq!(
                            candidate_children["children"].as_array().map(Vec::len),
                            Some(1)
                        );
                        for out in [
                            &candidates_by_height,
                            &candidate_by_hash,
                            &candidate_children,
                        ] {
                            for flag in ["chain_canonical", "proof_sealed", "safe", "finalized"] {
                                assert_eq!(out[flag].as_bool(), Some(false), "unexpected {flag}");
                            }
                        }
                        let location = run_nov_native_block_ledger_query_internal_v1(
                            "nov_getNativeTransactionLocation",
                            &serde_json::json!({
                                "chain_id": chain_id,
                                "native_execution_store_path": path,
                                "tx_hash": to_hex_prefixed_v1(&block.body.tx_hashes[0]),
                            }),
                            true,
                            None,
                        )
                        .expect("transaction location query should succeed");
                        assert_eq!(location["found"].as_bool(), Some(true));
                        assert_eq!(location["location"]["height"].as_u64(), Some(1));
                        let receipt = run_nov_native_block_ledger_query_internal_v1(
                            "nov_getNativeTransactionReceipt",
                            &serde_json::json!({
                                "chain_id": chain_id,
                                "native_execution_store_path": path,
                                "tx_hash": to_hex_prefixed_v1(&block.body.tx_hashes[0]),
                            }),
                            true,
                            None,
                        )
                        .expect("transaction receipt query should verify durable commitment");
                        assert_eq!(receipt["found"].as_bool(), Some(true));
                        assert!(receipt["receipt"].is_object());
                        let recovery =
                            recover_nov_native_block_ledger_from_aoem_v1(&serde_json::json!({
                                "chain_id": chain_id,
                                "native_execution_store_path": path,
                                "aoem_state_namespace": state_namespace,
                                "aoem_owned_gate_config": {
                                    "production_candidate": true,
                                    "shadow": false,
                                    "compare": true,
                                    "source": "test_restart_recovery"
                                },
                            }))
                            .expect("durable block ledger should hydrate after reopen");
                        assert_eq!(recovery["hydrated_block_count"].as_u64(), Some(1));
                    })
                })
            },
        )
    }

